      {id:'fv', t:'frei verfügbarer Betrag', e:'€', f:'ne + kg - (mi + lh + vs + au + kr)'},
      {id:'mr', t:'höchstens tragbare neue Monatsrate', kurz:'tragbare Rate', e:'€', f:'ne + kg - (mi + lh + vs + au + kr) - sr'}
