      {id:'an', t:'Anteile insgesamt (Sparplan)', f:'br / p1 + br / p2 + br / p3'},
      {id:'dk', t:'durchschnittlicher Einstandspreis Sparplan', e:'€', f:'3 * br / (br / p1 + br / p2 + br / p3)'},
      {id:'dm', t:'durchschnittlicher Preis bei fester Stückzahl (Kollege)', kurz:'Durchschnittspreis Kollege', e:'€', f:'(p1 + p2 + p3) / 3'}
